-- Append the ten questions reviewed and approved by the host.
WITH base AS (SELECT coalesce(max(sort_order),0) AS last_order FROM question_ideas)
INSERT INTO question_ideas(id,category,sort_order,content)
SELECT seed.id,seed.category,base.last_order+seed.offset_order,seed.content
FROM base CROSS JOIN (VALUES
 ('tech-gps','Tech',1,'{"kind": "mc", "prompt": "What does GPS stand for?", "timeSeconds": 20, "points": 1000, "options": ["Global Positioning System", "General Positioning Service", "Geographic Planning System", "Global Processing Service"], "correctIndex": 0, "revealFact": "GPS uses signals from satellites to help determine your location."}'::jsonb),
 ('science-photosynthesis','Science',2,'{"kind": "mc", "prompt": "Which gas do plants absorb from the air during photosynthesis?", "timeSeconds": 20, "points": 1000, "options": ["Oxygen", "Nitrogen", "Carbon dioxide", "Helium"], "correctIndex": 2, "revealFact": "Plants use light energy to turn carbon dioxide and water into sugars."}'::jsonb),
 ('geography-colosseum','Geography',3,'{"kind": "mc", "prompt": "Which city is famous for the Colosseum?", "timeSeconds": 20, "points": 1000, "options": ["Athens", "Rome", "Paris", "Istanbul"], "correctIndex": 1, "revealFact": "The Colosseum is an ancient Roman amphitheatre."}'::jsonb),
 ('general-chess-knight','General',4,'{"kind": "mc", "prompt": "In chess, which piece moves in an L-shape?", "timeSeconds": 20, "points": 1000, "options": ["Bishop", "Rook", "Queen", "Knight"], "correctIndex": 3, "revealFact": "The knight can jump over other pieces."}'::jsonb),
 ('general-bohemian-rhapsody','General',5,'{"kind": "mc", "prompt": "Which band released the song “Bohemian Rhapsody”?", "timeSeconds": 20, "points": 1000, "options": ["Queen", "The Beatles", "ABBA", "Pink Floyd"], "correctIndex": 0, "revealFact": "“Bohemian Rhapsody” appeared on Queen’s album A Night at the Opera."}'::jsonb),
 ('tech-wireless-router','Tech',6,'{"kind": "mc", "prompt": "Which device commonly connects your home network to Wi-Fi devices?", "timeSeconds": 20, "points": 1000, "options": ["Scanner", "Projector", "Wireless router", "External hard drive"], "correctIndex": 2, "revealFact": "A wireless router lets compatible devices join a network without cables."}'::jsonb),
 ('safety-payment-verification','Work safety',7,'{"kind": "mc", "prompt": "An unexpected message asks you to urgently transfer money for your manager. What should you do first?", "timeSeconds": 20, "points": 1000, "options": ["Transfer it immediately", "Verify through a known, trusted contact method", "Reply with your banking password", "Forward it to everyone"], "correctIndex": 1, "revealFact": "Scammers often impersonate trusted people and use urgency to discourage checks."}'::jsonb),
 ('geography-machu-picchu','Geography',8,'{"kind": "mc", "prompt": "Which country is home to Machu Picchu?", "timeSeconds": 20, "points": 1000, "options": ["Mexico", "Chile", "Brazil", "Peru"], "correctIndex": 3, "revealFact": "Machu Picchu is an Inca site in the Andes Mountains."}'::jsonb),
 ('general-al-dente','General',9,'{"kind": "mc", "prompt": "What does “al dente” describe when cooking pasta?", "timeSeconds": 20, "points": 1000, "options": ["Firm to the bite", "Served cold", "Cooked without salt", "Covered in cheese"], "correctIndex": 0, "revealFact": "“Al dente” is an Italian expression meaning “to the tooth.”"}'::jsonb),
 ('science-heart','Science',10,'{"kind": "mc", "prompt": "Which organ pumps blood around the human body?", "timeSeconds": 20, "points": 1000, "options": ["Liver", "Lungs", "Heart", "Kidneys"], "correctIndex": 2, "revealFact": "The heart’s right side pumps blood toward the lungs; its left side pumps blood toward the body."}'::jsonb)
) AS seed(id,category,offset_order,content);
